import {deliveryLabel,notificationHealth} from './notification-status.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const date=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未取得';
const statuses={draft:'待确认',active:'已启用',paused:'已暂停',completed:'已触发完成',expired:'已过期',archived:'已归档'};
const deliveries={pending:'待发送',sending:'发送中',failed:'发送失败',unknown:'结果待核对',accepted:'通道已接收'};
const marketLabels={idle:'待命（无价格规则）',unconfigured:'待配置',connecting:'连接中',connected:'已连接',stale:'心跳中断',disconnected:'连接中断','permission-denied':'权限未通过','runtime-missing':'运行库缺失',failed:'启动失败',stopped:'已停止'};
export const bellIcon='<img class="monitor-icon" src="/assets/wujian/icons/bell.svg" alt="">';

export function createMonitorUI({api,toast,onNavigate=()=>location.assign('/?view=monitor')}){
 let status=null,rules=[],events=[],catalog=[],tab='rules',search='',root=null,stream,refreshTimer,poll,loading=false;
 const dialog=document.createElement('dialog');dialog.id='monitorDialog';dialog.className='monitor-dialog';document.body.append(dialog);
 function close(){dialog.close();}
 function show(title,html){if(dialog.open)dialog.close();dialog.innerHTML=`<header><h2>${esc(title)}</h2><button type="button" class="monitor-close" aria-label="关闭提醒窗口">×</button></header>${html}`;dialog.querySelector('.monitor-close').onclick=close;dialog.showModal();}
 const post=(path,input={})=>api('/api/monitor/'+path,{method:'POST',body:JSON.stringify(input)});
 const bell=document.createElement('button');bell.type='button';bell.id='monitorBell';bell.className='monitor-bell';bell.title='盯盘提醒与未读消息';bell.setAttribute('aria-label','打开盯盘提醒');bell.innerHTML=bellIcon+'<span class="monitor-count"></span><span class="monitor-health">提醒连接中</span>';
 const parent=document.querySelector('.top-actions')||document.querySelector('.cockpit-header');if(parent){const anchor=parent.querySelector('#assistantButton');anchor?parent.insertBefore(bell,anchor):parent.prepend(bell);}bell.onclick=()=>openInbox();
 function updateBell(){const count=bell.querySelector('.monitor-count'),health=bell.querySelector('.monitor-health');count.textContent=status?.unread?String(status.unread):'';const normal=status?.runtime&&status?.market?.status==='connected'&&status?.market?.heartbeatFresh;health.textContent=!status?'服务未连接':normal?'提醒运行中':status?.activeRules?'监控待核验':'盯盘提醒';health.className='monitor-health'+(status?.activeRules&&!normal?' warn':'');bell.setAttribute('aria-label',`打开盯盘提醒，${status?.unread||0}条未读`);}
 async function refresh(){if(loading)return;loading=true;try{[status,{items:rules},{items:events}]=await Promise.all([api('/api/monitor/status'),api('/api/monitor/rules'),api('/api/monitor/events')]);updateBell();if(root?.isConnected){updateStatus();if(tab==='rules'||tab==='events')renderBody();else updateConnectionStatus();}}catch{status=null;updateBell();}finally{loading=false;}}
 function requestRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>void refresh(),350);}
 function start(){stream=new EventSource('/api/monitor/stream');for(const type of ['trigger','change','status'])stream.addEventListener(type,requestRefresh);stream.onerror=()=>{bell.querySelector('.monitor-health').textContent='提醒连接中断';};poll=setInterval(()=>void refresh(),15000);void refresh();}
 function updateStatus(){const box=root?.querySelector('.monitor-statusbar');if(!box)return;const desktop=notificationHealth(status?.desktop,'desktop'),phone=notificationHealth(status?.phone,'feishu');box.innerHTML=`<div><small>监控服务</small><b class="${status?.runtime?'':'warn'}">${status?.runtime?'正在运行':'已停止'}</b></div><div><small>行情源连接</small><b class="${status?.market?.status==='connected'&&status?.market?.heartbeatFresh?'':'warn'}">${esc(status?.market?.provider==='sina'&&status?.market?.status==='connected'?'公开行情 · 10秒检查':marketLabels[status?.market?.status]||'未核验')}</b></div><div><small>电脑通知</small><b class="${desktop.confirmed?'':'warn'}">${esc(desktop.text)}</b></div><div><small>手机通知</small><b class="${phone.confirmed?'':'warn'}">${esc(phone.text)}</b></div>`;}
 async function mountPage(node){root=node;root.innerHTML=`<section class="monitor-page"><div class="monitor-toolbar"><div><h2>盯盘提醒</h2><p>已启用提醒 ${status?.activeRules||0} 条</p></div><div class="monitor-actions"><button class="secondary" id="monitorRuntime">${status?.runtime?'暂停全部监控':'恢复监控'}</button><button class="primary" id="monitorCreate">添加提醒</button></div></div><div class="monitor-statusbar"></div><div class="monitor-tabs" role="tablist"><button data-monitor-tab="rules">我的监控</button><button data-monitor-tab="events">提醒记录</button><button data-monitor-tab="settings">连接与通知</button></div><input class="monitor-search" type="search" placeholder="搜索品种、合约或条件" aria-label="搜索监控"><div class="monitor-body"></div></section>`;root.querySelector('#monitorCreate').onclick=()=>openEditor();root.querySelector('#monitorRuntime').onclick=async()=>{await post('runtime',{enabled:!status?.runtime});await refresh();root.querySelector('#monitorRuntime').textContent=status?.runtime?'暂停全部监控':'恢复监控';};root.querySelector('.monitor-search').oninput=event=>{search=event.target.value;renderBody();};root.querySelectorAll('[data-monitor-tab]').forEach(button=>button.onclick=()=>{tab=button.dataset.monitorTab;renderBody();});await refresh();updateStatus();renderBody();}
 function renderBody(){if(!root?.isConnected)return;root.querySelectorAll('[data-monitor-tab]').forEach(button=>{button.classList.toggle('active',button.dataset.monitorTab===tab);button.setAttribute('aria-selected',String(button.dataset.monitorTab===tab));});root.querySelector('.monitor-search').hidden=tab==='settings';const body=root.querySelector('.monitor-body');
  if(tab==='rules'){
   const rows=rules.filter(rule=>rule.status!=='archived'&&JSON.stringify([rule.members,rule.condition,rule.title]).toLowerCase().includes(search.toLowerCase()));
   body.innerHTML=rows.length?`<div class="monitor-table-wrap"><table class="monitor-table"><thead><tr><th>品种 / 合约</th><th>提醒条件</th><th>当前报价</th><th>状态 / 有效期</th><th>操作</th></tr></thead><tbody>${rows.map(rule=>`<tr><td><b>${esc(rule.title||rule.members.map(item=>item.name).join('、'))}</b><small>${esc(rule.members.map(item=>item.symbol).join('、'))}</small></td><td class="${rule.direction==='up'?'monitor-up':rule.direction==='down'?'monitor-down':'monitor-neutral'}">${esc(rule.condition)}<small>版本 ${rule.version} · ${rule.repeat?'重复提醒':'一次提醒'}</small></td><td>${rule.quotes?.length?rule.quotes.map(quote=>`${esc(quote.symbol)} ${esc(quote.last)}<small>${date(quote.quoteAt)}</small>`).join(''):'等待实时报价'}${rule.rollover?.length?'<small class="monitor-warning">主力已换月，请复核原合约</small>':''}</td><td>${statuses[rule.status]}<small>${esc(rule.observation)}</small><small>${rule.expiresAt?date(rule.expiresAt):'至取消或合约失效'}</small></td><td><div class="monitor-actions"><button class="quiet" data-edit="${rule.id}">编辑</button><button class="quiet" data-action="${rule.status==='active'?'pause':'activate'}" data-rule="${rule.id}">${rule.status==='active'?'暂停':rule.status==='completed'?'再次启用':'启用'}</button><button class="quiet" data-action="archive" data-rule="${rule.id}">归档</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="monitor-empty">暂无监控，添加你想关注的价格、异动或公告条件。</div>';
   body.querySelectorAll('[data-edit]').forEach(button=>button.onclick=()=>openEditor({id:button.dataset.edit}));body.querySelectorAll('[data-action]').forEach(button=>button.onclick=async()=>{try{await post(`rules/${button.dataset.rule}/${button.dataset.action}`);await refresh();toast('提醒状态已更新');}catch(error){toast(error.message,true);}});
  }else if(tab==='events'){
   const rows=events.filter(event=>JSON.stringify([event.name,event.symbol,event.label,event.condition]).toLowerCase().includes(search.toLowerCase()));body.innerHTML=rows.length?`<div class="monitor-table-wrap"><table class="monitor-table"><thead><tr><th>触发时间</th><th>品种 / 事件</th><th>条件与证据</th><th>消息送达</th><th></th></tr></thead><tbody>${rows.map(event=>`<tr><td>${date(event.triggeredAt)}<small>${event.readAt?'工作台已读':'工作台未读'}</small></td><td><b>${esc(event.name)}</b><small>${esc(event.symbol||event.label)}</small></td><td class="${event.direction==='up'?'monitor-up':event.direction==='down'?'monitor-down':'monitor-neutral'}">${esc(event.label)}<small>${esc(event.condition)}</small></td><td>${event.deliveries.map(item=>`${item.channel==='desktop'?'电脑':'手机'}：${esc(deliveryLabel(item))}<small>${esc(item.note)}</small>`).join('')||'仅工作台记录'}</td><td><button class="quiet" data-event="${event.id}">查看证据</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="monitor-empty">还没有触发记录。</div>';body.querySelectorAll('[data-event]').forEach(button=>button.onclick=()=>openEvent(button.dataset.event));
  }else renderSettings(body);
 }
 function updateConnectionStatus(){const node=root?.querySelector('#monitorConnectionStatus');if(node)node.textContent=(status?.market?.message||'待核验')+'；最近检查 '+date(status?.market?.lastCheck?.checkedAt)+'；有效新报价 '+(status?.market?.freshQuoteCount||0)+'/'+(status?.market?.subscribed||0)+'；最近失败 '+date(status?.market?.lastFailureAt)+(status?.market?.reason?'（'+status.market.reason+'）':'');const phone=root?.querySelector('#monitorPhoneStatus');if(phone)phone.textContent=status?.phone?.configured?'已绑定 · '+(status.phone.lastError|| (['unknown','failed'].includes(status.phone.lastDelivery?.status)?status.phone.lastDelivery.note:null)|| (status.phone.monitorChatBound?'本人单聊已绑定，请用测试消息核验送达':status.phone.ready?'请在本人小木单聊发送“绑定提醒”':'连接待核验')):'尚未绑定本人飞书';const open=root?.querySelector('#monitorOpenBot');if(open){open.hidden=!status?.phone?.botUrl;if(status?.phone?.botUrl)open.href=status.phone.botUrl;}const sources=root?.querySelector('#monitorSources');if(sources)sources.innerHTML=(status?.announcements||[]).map(source=>`<div class="monitor-source"><a href="${esc(source.url)}" target="_blank" rel="noreferrer">${esc(source.name)}</a><span class="${source.status==='ok'?'':'monitor-warning'}">${({ok:'已取得',partial:'部分正文缺失',unavailable:'来源未取得','not-checked':'待检查'})[source.status]||'检查中'}${source.checkedAt?' · 检查 '+date(source.checkedAt):''}${source.lastSuccessAt?' · 最近成功 '+date(source.lastSuccessAt):''}${source.reason?' · '+esc(source.reason):''}</span></div>`).join('');}
 function renderSettings(body){body.innerHTML=`<div class="monitor-settings"><section class="monitor-setting"><h3>期货行情来源</h3><p id="monitorConnectionStatus"></p><div class="monitor-provider"><label>行情源<select id="monitorProvider"><option value="sina">新浪公开行情（免账号）</option><option value="tqsdk">快期 / 天勤（自有账号）</option></select></label><button class="secondary" id="monitorProviderConnect">连接所选行情</button></div><p id="monitorPublicNotice" hidden>每10秒检查公开报价；可能延迟或中断，不保证逐笔更新。数据缺失或陈旧时暂停判断，不替代交易软件止损。</p><form id="monitorCredentials" class="monitor-credentials"><label>快期 / 天勤账号<input name="user" autocomplete="username" required></label><label>密码<input name="password" type="password" autocomplete="current-password" required></label><button class="secondary">保存并连接</button></form><p id="monitorCredentialNotice">Windows 上的行情凭据加密保存在本机，登录状态以实际权限核验为准。</p></section><section class="monitor-setting"><h3>电脑与手机通知</h3><p id="monitorPhoneStatus"></p><div class="monitor-actions"><button class="secondary" id="monitorBind">飞书扫码绑定</button><a class="secondary" id="monitorOpenBot" target="_blank" rel="noreferrer" hidden>打开飞书小木</a><button class="secondary" id="monitorDesktopTest">测试电脑通知</button><button class="secondary" id="monitorPhoneTest">测试手机通知</button></div><p>电脑休眠、关机或完全退出后停止；手机提醒需要电脑持续联网运行。</p></section><section class="monitor-setting"><h3>交易所公告覆盖</h3><div id="monitorSources"></div><button class="secondary" id="monitorSourceCheck">检查官方来源</button></section><section class="monitor-setting"><h3>监控记录</h3><p>${status?.interruption?'最近中断：'+date(status.interruption.from)+' → '+date(status.interruption.to)+' · '+esc(status.interruption.reason):'暂无已记录的中断'}</p><button class="secondary" id="monitorExport">导出监控备份</button></section></div>`;const provider=body.querySelector('#monitorProvider');provider.value=status?.market?.provider||'sina';const displayProvider=()=>{const publicSource=provider.value==='sina';body.querySelector('#monitorCredentials').hidden=publicSource;body.querySelector('#monitorCredentialNotice').hidden=publicSource;body.querySelector('#monitorPublicNotice').hidden=!publicSource;};provider.onchange=displayProvider;displayProvider();body.querySelector('#monitorProviderConnect').onclick=async()=>{try{await post('provider',{provider:provider.value});await refresh();toast(provider.value==='sina'?'正在检查免账号公开行情':'已切换自有账号行情');}catch(error){toast(error.message,true);}};updateConnectionStatus();body.querySelector('#monitorCredentials').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,submit=form.querySelector('button');submit.disabled=true;try{await api('/api/tq/login',{method:'POST',body:JSON.stringify({user:form.elements.user.value,password:form.elements.password.value,remember:true})});window.dispatchEvent(new Event('xiaomu:market-connection'));form.elements.password.value='';await refresh();toast('凭据已加密保存，正在核验行情权限');document.dispatchEvent(new Event('xiaomu:open-tq-login'));}catch(error){toast(error.message,true);}finally{submit.disabled=false;}};body.querySelector('#monitorBind').onclick=()=>bindPhone();for(const [id,channel] of [['#monitorDesktopTest','desktop'],['#monitorPhoneTest','feishu']])body.querySelector(id).onclick=async()=>{if(channel==='feishu'&&!status?.phone?.targetConfigured)return toast('先扫码绑定本人飞书',true);await post('test',{channels:[channel]});toast('测试消息已加入通知队列');await refresh();};body.querySelector('#monitorSourceCheck').onclick=async()=>{await post('sources/check');toast('正在分别检查六个官方来源');};body.querySelector('#monitorExport').onclick=async()=>{try{const saved=await post('export/file');toast('备份已保存：'+saved.path);}catch(error){toast(error.message,true);}};}
 async function openEditor({id=null,symbol=null}={}){
  symbol=String(symbol||'').toUpperCase().replace(/^(CZCE\.[A-Z]+)\d(\d{3})$/,'$1$2')||null;
  try{catalog=(await api('/api/monitor/contracts')).items;rules=(await api('/api/monitor/rules')).items;const rule=id?rules.find(item=>item.id===id):null;if(id&&!rule)throw Error('提醒草稿不存在');
   const members=rule?.members.map(item=>item.symbol)||[symbol].filter(Boolean),kind=rule?.kind||'price';
   show(rule?'核对提醒卡':'添加提醒',`<form class="monitor-editor" id="monitorRuleForm"><label>提醒类型<select name="kind"><option value="price">价格到位</option><option value="movement">短时异动</option><option value="announcement">交易所公告</option></select></label><label>提醒名称<input name="title" maxlength="100" value="${esc(rule?.title||'')}"></label><label class="wide">品种 / 具体合约<select name="symbols" ${kind==='price'?'':'multiple size="7"'} required>${catalog.map(item=>`<option value="${esc(item.symbol)}" ${members.includes(item.symbol)?'selected':''}>${esc(item.name)} · ${esc(item.symbol)} · ${esc(item.source)}</option>`).join('')}</select></label><div class="monitor-actions wide"><button type="button" id="monitorSelectAll">选择全部已支持品种</button><button type="button" id="monitorSelectWatch">选择已关注品种</button></div><label data-price-field>方向<select name="direction"><option value="up">上涨 / 达到或高于</option><option value="down">下跌 / 达到或低于</option></select></label><label data-price-field><span id="monitorThresholdLabel">目标价格</span><input name="threshold" type="number" min="0.000001" step="any" value="${esc(rule?.threshold??'')}"></label><label data-movement-field>观察窗口<select name="windowMinutes">${[1,3,5,15].map(n=>`<option value="${n}">${n}分钟</option>`).join('')}</select></label><label data-movement-field>冷却时间（分钟）<input name="cooldownMinutes" type="number" min="1" max="1440" value="${rule?.cooldownMinutes||15}"></label><label>截止时间（可选）<input name="expiresAt" type="datetime-local" value="${rule?.expiresAt?new Date(Date.parse(rule.expiresAt)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''}"></label><label class="monitor-inline"><input name="repeat" type="checkbox" ${rule?.repeat?'checked':''}>重复到价提醒</label><div class="monitor-actions wide"><label class="monitor-inline"><input name="desktop" type="checkbox" ${!rule||rule.channels.includes('desktop')?'checked':''}>电脑通知</label><label class="monitor-inline"><input name="feishu" type="checkbox" ${!rule||rule.channels.includes('feishu')?'checked':''}>手机飞书</label></div><div class="monitor-preview wide" id="monitorRulePreview"></div><p class="monitor-error wide" id="monitorRuleError" role="alert"></p><div class="monitor-actions wide"><button type="button" id="monitorSaveDraft">保存草稿</button><button class="primary" type="submit">确认启用</button></div></form>`);
   const form=dialog.querySelector('form');form.elements.kind.value=kind;form.elements.direction.value=rule?.direction||'up';form.elements.windowMinutes.value=String(rule?.windowMinutes||5);
   const selected=()=>[...form.elements.symbols.selectedOptions].map(option=>option.value);
   const update=()=>{const type=form.elements.kind.value;form.elements.symbols.multiple=type!=='price';form.elements.symbols.size=type==='price'?1:7;form.querySelectorAll('[data-price-field]').forEach(node=>node.hidden=type==='announcement');form.querySelectorAll('[data-movement-field]').forEach(node=>node.hidden=type!=='movement');form.elements.threshold.required=type!=='announcement';form.elements.repeat.disabled=type!=='price';dialog.querySelector('#monitorThresholdLabel').textContent=type==='movement'?'幅度（%）':'目标价格';dialog.querySelector('#monitorRulePreview').textContent=selected().join('、')+'；'+(type==='announcement'?'保证金、涨跌停板、手续费、交割及交易时间公告':type==='movement'?form.elements.windowMinutes.value+'分钟'+(form.elements.direction.value==='up'?'上涨':'下跌')+'达到'+(form.elements.threshold.value||'待填写')+'%':'最新成交价 '+(form.elements.direction.value==='up'?'≥':'≤')+' '+(form.elements.threshold.value||'待填写'))+'；'+(status?.market?.configured?'行情权限以连接状态为准':'实时行情尚待配置');};
   form.oninput=update;form.onchange=update;update();
   for(const [button,all] of [['#monitorSelectAll',true],['#monitorSelectWatch',false]])dialog.querySelector(button).onclick=()=>{if(form.elements.kind.value==='price')return toast('批量选择用于异动或公告提醒',true);const watched=rules.filter(item=>item.status!=='archived').flatMap(item=>item.members.map(member=>member.symbol));for(const option of form.elements.symbols.options)option.selected=all||watched.includes(option.value);update();};
   const save=async enable=>{if(!form.reportValidity())return;const buttons=[...form.querySelectorAll('button')];buttons.forEach(button=>button.disabled=true);try{const input={kind:form.elements.kind.value,title:form.elements.title.value,symbols:selected(),direction:form.elements.direction.value,threshold:Number(form.elements.threshold.value),windowMinutes:Number(form.elements.windowMinutes.value),cooldownMinutes:Number(form.elements.cooldownMinutes.value),repeat:form.elements.repeat.checked,expiresAt:form.elements.expiresAt.value?new Date(form.elements.expiresAt.value).toISOString():null,channels:['desktop','feishu'].filter(channel=>form.elements[channel].checked)};const saved=await post(id?'rules/'+id:'rules',input);if(enable)await post('rules/'+saved.id+'/activate');close();await refresh();toast(enable?'提醒已启用，运行状态请看连接栏':'提醒草稿已保存');}catch(error){dialog.querySelector('#monitorRuleError').textContent=error.message;}finally{buttons.forEach(button=>button.disabled=false);}};
   form.onsubmit=event=>{event.preventDefault();void save(true);};dialog.querySelector('#monitorSaveDraft').onclick=()=>save(false);
  }catch(error){toast(error.message,true);}
 }
 async function openEvent(id){try{const event=await api('/api/monitor/events/'+id);await post('events/'+id+'/read');const e=event.evidence||{};show(event.name+' · '+event.label,`<dl class="monitor-evidence"><dt>合约 / 条件</dt><dd>${esc(event.symbol||'通知测试')}<br>${esc(event.condition)}</dd><dt>行情 / 触发时间</dt><dd>${date(event.quoteAt)}<br>${date(event.triggeredAt)}</dd><dt>触发数值</dt><dd>${esc(event.price??(event.kind==='test'?'不涉及行情':'公告事件'))}${event.kind==='movement'?'<br>窗口涨跌 '+event.value.toFixed(3)+'%':''}</dd><dt>观测依据</dt><dd>${e.baseline?'起点 '+esc(e.baseline.price)+'，时间 '+date(new Date(e.baseline.at).toISOString()):esc(e.notice||(event.kind==='test'?'本人主动测试通知，不涉及交易条件':'按有效实时报价核对条件'))}<br>${esc(event.source)}</dd><dt>通知状态</dt><dd>${event.deliveries.map(item=>(item.channel==='desktop'?'电脑':'手机')+'：'+esc(deliveryLabel(item))+' '+esc(item.note)).join('<br>')}</dd>${e.url?`<dt>官方来源</dt><dd><a href="${esc(e.url)}" target="_blank" rel="noreferrer">${esc(e.title)}</a><br>发布时间：${esc(e.published||'未核验')}</dd>`:''}</dl><section><h3>本人收到确认</h3>${event.deliveries.map(item=>`<div class="monitor-actions"><b>${item.channel==='desktop'?'电脑':'手机'}</b><button type="button" data-receipt="${item.channel}" data-received="true">我已看到</button><button type="button" data-receipt="${item.channel}" data-received="false">没有收到</button><small>${item.receipt?date(item.receipt.at)+' · '+(item.receipt.received?'已看到':'未收到'):'尚未确认'}</small></div>`).join('')}</section>${e.text?`<details><summary>官方正文</summary><p class="monitor-article">${esc(e.text)}</p></details>`:''}`);
   dialog.querySelectorAll('[data-receipt]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await post('events/'+id+'/receipt',{channel:button.dataset.receipt,received:button.dataset.received==='true'});await openEvent(id)}catch(error){toast(error.message,true)}finally{button.disabled=false}});
   await refresh();}catch(error){toast(error.message,true);}}
 async function openInbox(){await refresh();show('盯盘提醒',events.length?events.slice(0,8).map(event=>`<button class="monitor-inbox-item" data-event="${event.id}"><b class="${event.direction==='up'?'monitor-up':event.direction==='down'?'monitor-down':''}">${esc(event.name)} · ${esc(event.label)} ${event.readAt?'':'（未读）'}</b><small>${esc(event.condition)} · ${date(event.triggeredAt)}</small></button>`).join(''):'<p>暂无提醒记录。</p>');dialog.insertAdjacentHTML('beforeend','<div class="monitor-actions"><button id="monitorInboxManage">管理监控</button><button id="monitorInboxAdd" class="primary">添加提醒</button></div>');dialog.querySelectorAll('[data-event]').forEach(button=>button.onclick=()=>openEvent(button.dataset.event));dialog.querySelector('#monitorInboxManage').onclick=()=>{close();onNavigate();};dialog.querySelector('#monitorInboxAdd').onclick=()=>openEditor();}
 async function bindPhone(){show('绑定本人飞书','<p id="monitorBindState">正在生成绑定二维码…</p><div id="monitorBindQR"></div>');try{const started=await api('/api/feishu/bind/start',{method:'POST',body:'{}'});let pending=true;const check=async()=>{if(!pending||!dialog.open)return;try{const binding=await api('/api/feishu/bind/status',{method:'POST',body:JSON.stringify({id:started.id})});const state=dialog.querySelector('#monitorBindState');if(!state)return;state.textContent=({preparing:'正在准备二维码',waiting:'请用本人飞书扫码确认',bound:'绑定完成',expired:'二维码已过期，请重新绑定',failed:binding.error||'绑定失败',cancelled:'绑定已取消'})[binding.status]||binding.status;if(binding.qr)dialog.querySelector('#monitorBindQR').innerHTML=`<img class="monitor-qr" src="${esc(binding.qr)}" alt="飞书本人绑定二维码">`;if(['bound','expired','failed','cancelled'].includes(binding.status)){pending=false;await refresh();return;}setTimeout(check,1500);}catch(error){const state=dialog.querySelector('#monitorBindState');if(state)state.textContent=error.message;pending=false;}};void check();dialog.addEventListener('close',()=>{pending=false;void api('/api/feishu/bind/cancel',{method:'POST',body:JSON.stringify({id:started.id})}).catch(()=>{});},{once:true});}catch(error){dialog.querySelector('#monitorBindState').textContent=error.message;}}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-monitor-draft]');if(button)void openEditor({id:button.dataset.monitorDraft});});
 start();const initialEvent=new URLSearchParams(location.search).get('monitorEvent');if(initialEvent)setTimeout(()=>void openEvent(initialEvent),700);
 return {mountPage,openEditor,openInbox,openEvent,refresh,stop(){stream?.close();clearInterval(poll);clearTimeout(refreshTimer);},draftButtons(ids=[]){return ids.map(id=>`<button class="secondary" data-monitor-draft="${esc(id)}">核对提醒卡</button>`).join('');}};
}
